diff --git a/backend/internal/service/gift_card_service.go b/backend/internal/service/gift_card_service.go
new file mode 100644
index 00000000..2ddf3294
--- /dev/null
+++ b/backend/internal/service/gift_card_service.go
@@ -0,0 +1,96 @@
+package service
+
+import (
+	"context"
+	"errors"
+	"strings"
+	"time"
+)
+
+// Sentinel refusals. A card the caller may not spend answers with the reason
+// rather than a bare false: the handler that follows maps each one to its own
+// code and Indonesian copy, and "saldo kurang" and "kadaluarsa" send the
+// cashier down different paths.
+var (
+	ErrGiftCardNotFound      = errors.New("gift card: no card with that code")
+	ErrGiftCardInactive      = errors.New("gift card: this card is no longer active")
+	ErrGiftCardExpired       = errors.New("gift card: this card has expired")
+	ErrGiftCardAmountInvalid = errors.New("gift card: amount must be positive")
+	ErrGiftCardBalanceLow    = errors.New("gift card: balance is lower than the amount being redeemed")
+)
+
+// GiftCard is the slice of a card this service decides on. It moves to
+// domain/gift_card.go once the repository and handler land; nothing outside
+// this file reads it yet.
+type GiftCard struct {
+	Code string
+	// Rupiah, BIGINT, never a float.
+	BalanceIDR int64
+	IsActive   bool
+	// nil means the card never expires.
+	ExpiresAt *time.Time
+}
+
+// giftCardStore is the repository surface Redeem needs, declared here so the
+// service is testable before backend/internal/repository/gift_card_repo.go
+// exists.
+type giftCardStore interface {
+	FindByCode(ctx context.Context, code string) (*GiftCard, error)
+	// Deduct subtracts amount from the card's balance in ONE conditional
+	// statement (UPDATE ... WHERE code = $1 AND balance_idr >= $2) and returns
+	// ErrGiftCardBalanceLow when no row matched. The balance check below is for
+	// the message the cashier reads; this one is what stops two terminals
+	// spending the same last rupiah, so it may not be relaxed into a read
+	// followed by a write.
+	Deduct(ctx context.Context, code string, amount int64) error
+}
+
+type GiftCardService struct {
+	store giftCardStore
+	// now is injected so the expiry branch is testable without waiting for a
+	// clock.
+	now func() time.Time
+}
+
+func NewGiftCardService(store giftCardStore) *GiftCardService {
+	return &GiftCardService{store: store, now: time.Now}
+}
+
+// Redeem spends amount off the card named by code, refusing a card that is
+// unknown, deactivated, past its expiry, or short of the amount.
+func (s *GiftCardService) Redeem(ctx context.Context, code string, amount int64) error {
+	code = normalizeGiftCardCode(code)
+	if code == "" {
+		return ErrGiftCardNotFound
+	}
+	if amount <= 0 {
+		return ErrGiftCardAmountInvalid
+	}
+
+	card, err := s.store.FindByCode(ctx, code)
+	if err != nil {
+		return err
+	}
+	if card == nil {
+		return ErrGiftCardNotFound
+	}
+	if !card.IsActive {
+		return ErrGiftCardInactive
+	}
+	// Expiry is refused before the balance so a dead card never reports a
+	// money problem the cashier would try to solve by topping it up.
+	if card.ExpiresAt != nil && !card.ExpiresAt.After(s.now()) {
+		return ErrGiftCardExpired
+	}
+	if card.BalanceIDR < amount {
+		return ErrGiftCardBalanceLow
+	}
+
+	return s.store.Deduct(ctx, code, amount)
+}
+
+// Cards are read off plastic and typed by hand, so case and stray spaces are
+// the user's, not the card's.
+func normalizeGiftCardCode(code string) string {
+	return strings.ToUpper(strings.TrimSpace(code))
+}
diff --git a/backend/internal/service/gift_card_service_test.go b/backend/internal/service/gift_card_service_test.go
new file mode 100644
index 00000000..66ad325c
--- /dev/null
+++ b/backend/internal/service/gift_card_service_test.go
@@ -0,0 +1,127 @@
+package service
+
+import (
+	"context"
+	"errors"
+	"testing"
+	"time"
+)
+
+type fakeGiftCardStore struct {
+	card      *GiftCard
+	findErr   error
+	deducted  int64
+	deductErr error
+}
+
+func (f *fakeGiftCardStore) FindByCode(ctx context.Context, code string) (*GiftCard, error) {
+	if f.findErr != nil {
+		return nil, f.findErr
+	}
+	if f.card == nil || f.card.Code != code {
+		return nil, nil
+	}
+	return f.card, nil
+}
+
+func (f *fakeGiftCardStore) Deduct(ctx context.Context, code string, amount int64) error {
+	if f.deductErr != nil {
+		return f.deductErr
+	}
+	f.deducted = amount
+	return nil
+}
+
+func giftCardFixture() *GiftCard {
+	exp := time.Date(2026, 12, 31, 0, 0, 0, 0, time.UTC)
+	return &GiftCard{Code: "KITA-8812", BalanceIDR: 150_000, IsActive: true, ExpiresAt: &exp}
+}
+
+func newGiftCardServiceAt(store giftCardStore, now time.Time) *GiftCardService {
+	s := NewGiftCardService(store)
+	s.now = func() time.Time { return now }
+	return s
+}
+
+func TestGiftCardRedeem(t *testing.T) {
+	today := time.Date(2026, 10, 8, 9, 0, 0, 0, time.UTC)
+
+	t.Run("spends the amount on a live card", func(t *testing.T) {
+		store := &fakeGiftCardStore{card: giftCardFixture()}
+		if err := newGiftCardServiceAt(store, today).Redeem(context.Background(), " kita-8812 ", 50_000); err != nil {
+			t.Fatalf("Redeem: %v", err)
+		}
+		if store.deducted != 50_000 {
+			t.Fatalf("deducted = %d, want 50000", store.deducted)
+		}
+	})
+
+	cases := []struct {
+		name   string
+		card   *GiftCard
+		amount int64
+		want   error
+	}{
+		{"unknown code", nil, 50_000, ErrGiftCardNotFound},
+		{"zero amount", giftCardFixture(), 0, ErrGiftCardAmountInvalid},
+		{"negative amount", giftCardFixture(), -1, ErrGiftCardAmountInvalid},
+		{"balance one rupiah short", func() *GiftCard {
+			c := giftCardFixture()
+			c.BalanceIDR = 49_999
+			return c
+		}(), 50_000, ErrGiftCardBalanceLow},
+		{"expired yesterday", func() *GiftCard {
+			c := giftCardFixture()
+			exp := today.Add(-24 * time.Hour)
+			c.ExpiresAt = &exp
+			return c
+		}(), 50_000, ErrGiftCardExpired},
+		{"expires exactly now", func() *GiftCard {
+			c := giftCardFixture()
+			exp := today
+			c.ExpiresAt = &exp
+			return c
+		}(), 50_000, ErrGiftCardExpired},
+		{"deactivated", func() *GiftCard {
+			c := giftCardFixture()
+			c.IsActive = false
+			return c
+		}(), 50_000, ErrGiftCardInactive},
+		{"expired and short at once reports expiry", func() *GiftCard {
+			c := giftCardFixture()
+			c.BalanceIDR = 1
+			exp := today.Add(-time.Hour)
+			c.ExpiresAt = &exp
+			return c
+		}(), 50_000, ErrGiftCardExpired},
+	}
+	for _, tc := range cases {
+		t.Run(tc.name, func(t *testing.T) {
+			store := &fakeGiftCardStore{card: tc.card}
+			err := newGiftCardServiceAt(store, today).Redeem(context.Background(), "KITA-8812", tc.amount)
+			if !errors.Is(err, tc.want) {
+				t.Fatalf("err = %v, want %v", err, tc.want)
+			}
+			if store.deducted != 0 {
+				t.Fatalf("a refused redeem deducted %d", store.deducted)
+			}
+		})
+	}
+
+	t.Run("no expiry date never expires", func(t *testing.T) {
+		card := giftCardFixture()
+		card.ExpiresAt = nil
+		store := &fakeGiftCardStore{card: card}
+		if err := newGiftCardServiceAt(store, today.AddDate(50, 0, 0)).Redeem(context.Background(), "KITA-8812", 150_000); err != nil {
+			t.Fatalf("Redeem: %v", err)
+		}
+	})
+
+	t.Run("the store's conditional deduct still decides", func(t *testing.T) {
+		store := &fakeGiftCardStore{card: giftCardFixture(), deductErr: ErrGiftCardBalanceLow}
+		err := newGiftCardServiceAt(store, today).Redeem(context.Background(), "KITA-8812", 50_000)
+		if !errors.Is(err, ErrGiftCardBalanceLow) {
+			t.Fatalf("err = %v, want ErrGiftCardBalanceLow", err)
+		}
+	})
+}

