@@ -0,0 +1,90 @@
+package service
+
+import (
+	"context"
+	"testing"
+
+	"github.com/google/uuid"
+
+	"github.com/kitapos/kitapos/internal/domain"
+	"github.com/kitapos/kitapos/internal/repository"
+)
+
+type stubFeeRateRepo struct {
+	repository.RestaurantRepository
+	orgID uuid.UUID
+	sub   domain.Subscription
+	asked string
+}
+
+func (s *stubFeeRateRepo) GetByOutlet(context.Context, string) (*domain.Restaurant, error) {
+	return &domain.Restaurant{ID: s.orgID}, nil
+}
+
+func (s *stubFeeRateRepo) SubscriptionByOrg(_ context.Context, orgID string) (domain.Subscription, error) {
+	s.asked = orgID
+	return s.sub, nil
+}
+
+func TestPlatformFeeRateForOutlet(t *testing.T) {
+	cases := []struct {
+		name string
+		sub  domain.Subscription
+		want domain.PlatformFeeRate
+	}{
+		{
+			// No deal of its own: SubscriptionByOrg has already folded the plan
+			// catalog in, so 2% arrives as data rather than as a literal here.
+			name: "follows the catalog",
+			sub:  domain.Subscription{PlatformFeeType: domain.PlatformFeePercentage, PlatformFeeBPS: 200},
+			want: domain.PlatformFeeRate{Type: domain.PlatformFeePercentage, BPS: 200},
+		},
+		{
+			name: "negotiated percentage wins over the catalog",
+			sub:  domain.Subscription{PlatformFeeType: domain.PlatformFeePercentage, PlatformFeeBPS: 130},
+			want: domain.PlatformFeeRate{Type: domain.PlatformFeePercentage, BPS: 130},
+		},
+		{
+			// The case a bare-bps accessor cannot express: billing this org at
+			// 200 bps, or at 0, are both wrong.
+			name: "fixed deal keeps its per-order amount",
+			sub:  domain.Subscription{PlatformFeeType: domain.PlatformFeeFixed, PlatformFeeFixedAmount: 1000},
+			want: domain.PlatformFeeRate{Type: domain.PlatformFeeFixed, FixedAmount: 1000},
+		},
+	}
+	for _, tc := range cases {
+		t.Run(tc.name, func(t *testing.T) {
+			orgID := uuid.New()
+			repo := &stubFeeRateRepo{orgID: orgID, sub: tc.sub}
+			got, err := NewRestaurantService(repo).PlatformFeeRateForOutlet(context.Background(), "outlet-1")
+			if err != nil {
+				t.Fatalf("PlatformFeeRateForOutlet: %v", err)
+			}
+			if got != tc.want {
+				t.Errorf("rate = %+v, want %+v", got, tc.want)
+			}
+			if repo.asked != orgID.String() {
+				t.Errorf("resolved against org %q, want %q", repo.asked, orgID)
+			}
+			if err := got.Validate(); err != nil {
+				t.Errorf("Validate: %v", err)
+			}
+		})
+	}
+}
+
+// A fixed deal prices per paid order, so the rate must survive the trip as an
+// amount: at 1000 the fee is the amount per order, not a share of the subtotal.
+func TestPlatformFeeRateForOutletFixedAmountBills(t *testing.T) {
+	repo := &stubFeeRateRepo{
+		orgID: uuid.New(),
+		sub:   domain.Subscription{PlatformFeeType: domain.PlatformFeeFixed, PlatformFeeFixedAmount: 1000},
+	}
+	rate, err := NewRestaurantService(repo).PlatformFeeRateForOutlet(context.Background(), "outlet-1")
+	if err != nil {
+		t.Fatalf("PlatformFeeRateForOutlet: %v", err)
+	}
+	if got := rate.Amount(5_000_000, 3); got != 3000 {
+		t.Errorf("Amount over 3 orders = %d, want 3000", got)
+	}
+}
diff --git a/backend/internal/service/restaurant_service.go b/backend/internal/service/restaurant_service.go
index 8168cf32..6bcd185e 100644
--- a/backend/internal/service/restaurant_service.go
+++ b/backend/internal/service/restaurant_service.go
@@ -45,3 +45,30 @@ func (s *RestaurantService) UpdateRestaurant(ctx context.Context, outletID strin
 	}
 	return s.repo.Update(ctx, outletID, r)
 }
+
+// PlatformFeeRateForOutlet resolves the KITAPOS platform fee that applies to the
+// outlet's order volume. The rate is a property of the ORG, so the outlet is
+// only an address for finding it: outlets under one org never carry different
+// rates, and whether an outlet is billed at all is a separate switch
+// (outlets.table_ordering_active) that this does not read.
+//
+// The fee is returned as the whole rate rather than a bps number because a
+// negotiated `fixed` deal prices per paid order and has no meaningful bps; a
+// bare bps would resolve such an org to 0 and silently stop billing it. An org
+// with no deal of its own resolves to the plan catalog rate inside
+// SubscriptionByOrg, never to a constant here, so a catalog change reaches it.
+func (s *RestaurantService) PlatformFeeRateForOutlet(ctx context.Context, outletID string) (domain.PlatformFeeRate, error) {
+	rest, err := s.repo.GetByOutlet(ctx, outletID)
+	if err != nil {
+		return domain.PlatformFeeRate{}, err
+	}
+	sub, err := s.repo.SubscriptionByOrg(ctx, rest.ID.String())
+	if err != nil {
+		return domain.PlatformFeeRate{}, err
+	}
+	return domain.PlatformFeeRate{
+		Type:        sub.PlatformFeeType,
+		BPS:         sub.PlatformFeeBPS,
+		FixedAmount: sub.PlatformFeeFixedAmount,
+	}, nil
+}

diff --git a/backend/internal/service/gift_card_service.go b/backend/internal/service/gift_card_service.go
new file mode 100644
index 00000000..8961bec1
--- /dev/null
+++ b/backend/internal/service/gift_card_service.go
@@ -0,0 +1,119 @@
+package service
+
+import (
+	"context"
+	"errors"
+	"strings"
+	"time"
+
+	"github.com/kitapos/kitapos/internal/repository"
+)
+
+var (
+	ErrGiftCardCodeRequired  = errors.New("gift card: a code is required")
+	ErrGiftCardAmountInvalid = errors.New("gift card: the redeemed amount must be positive")
+	ErrGiftCardNotFound      = errors.New("gift card: no card carries that code")
+	ErrGiftCardExpired       = errors.New("gift card: this card has expired")
+	ErrGiftCardInsufficient  = errors.New("gift card: the remaining balance is below the redeemed amount")
+)
+
+// GiftCard is the slice of a card this service reasons about. Money is BIGINT
+// IDR like everywhere else, and ExpiresAt is nil for a card that never expires
+// rather than a far-future date, so "no expiry" cannot be read as "expires".
+type GiftCard struct {
+	Code      string
+	Balance   int64
+	ExpiresAt *time.Time
+}
+
+// Declared at the consumer so a test can inject a fake without importing the
+// repository package.
+//
+// Debit is CONDITIONAL on purpose: it must apply the balance check inside its
+// own statement and report whether it actually moved money. Checking the
+// balance in Go and then debiting leaves a window where two concurrent
+// redemptions of the same card both pass the check and the card goes negative.
+// The read below exists to say WHICH refusal happened, never to authorise one.
+type giftCardRepo interface {
+	GetByCode(ctx context.Context, code string) (*GiftCard, error)
+	Debit(ctx context.Context, code string, amount int64, now time.Time) (applied bool, err error)
+}
+
+type GiftCardService struct {
+	repo giftCardRepo
+	// now is injected so the expiry branch is testable without waiting for a
+	// clock or writing a card dated in the past.
+	now func() time.Time
+}
+
+func NewGiftCardService(repo giftCardRepo) *GiftCardService {
+	return &GiftCardService{repo: repo, now: time.Now}
+}
+
+// Redeem takes amount off the card named by code, refusing an expired card and
+// one whose remaining balance is below the amount. The refusal is decided from
+// the card's own row, and the write is the repo's conditional debit, so a
+// second concurrent redemption that slips past the check still fails at the
+// statement and comes back as a refusal rather than as an overdrawn card.
+func (s *GiftCardService) Redeem(ctx context.Context, code string, amount int64) error {
+	// Codes are handed over by humans reading a printed card, so case and
+	// stray spacing carry no meaning. The repo lookup must store them folded
+	// the same way.
+	code = strings.ToUpper(strings.TrimSpace(code))
+	if code == "" {
+		return ErrGiftCardCodeRequired
+	}
+	if amount <= 0 {
+		return ErrGiftCardAmountInvalid
+	}
+
+	now := s.now()
+	card, err := s.repo.GetByCode(ctx, code)
+	if errors.Is(err, repository.ErrNotFound) {
+		return ErrGiftCardNotFound
+	}
+	if err != nil {
+		return err
+	}
+	if err := card.refuse(now, amount); err != nil {
+		return err
+	}
+
+	applied, err := s.repo.Debit(ctx, code, amount, now)
+	if err != nil {
+		return err
+	}
+	if applied {
+		return nil
+	}
+	// The card passed the check a moment ago and the statement still declined,
+	// so another redemption landed in between. Re-read to name the reason, and
+	// fall back to the insufficient balance: that is what a lost race means.
+	fresh, err := s.repo.GetByCode(ctx, code)
+	if errors.Is(err, repository.ErrNotFound) {
+		return ErrGiftCardNotFound
+	}
+	if err != nil {
+		return err
+	}
+	if err := fresh.refuse(now, amount); err != nil {
+		return err
+	}
+	return ErrGiftCardInsufficient
+}
+
+// refuse answers with the reason this card cannot pay amount, or nil when it
+// can. Expiry is checked before the balance so a spent, long-dead card reads as
+// expired rather than sending someone to top it up.
+func (c *GiftCard) refuse(now time.Time, amount int64) error {
+	if c == nil {
+		return ErrGiftCardNotFound
+	}
+	if c.ExpiresAt != nil && !now.Before(*c.ExpiresAt) {
+		return ErrGiftCardExpired
+	}
+	if c.Balance < amount {
+		return ErrGiftCardInsufficient
+	}
+	return nil
+}
diff --git a/backend/internal/service/gift_card_service_test.go b/backend/internal/service/gift_card_service_test.go
