index 00000000..5725f058
--- /dev/null
+++ b/backend/internal/service/gift_card_service_test.go
@@ -0,0 +1,121 @@
+package service
+
+import (
+	"context"
+	"errors"
+	"testing"
+	"time"
+
+	"github.com/kitapos/kitapos/internal/repository"
+)
+
+type fakeGiftCardRepo struct {
+	card       *GiftCard
+	debits     []int64
+	applyDebit bool
+	// afterDebit replaces the card before the service re-reads it, standing in
+	// for a concurrent redemption that landed between check and write.
+	afterDebit *GiftCard
+}
+
+func (f *fakeGiftCardRepo) GetByCode(ctx context.Context, code string) (*GiftCard, error) {
+	if f.card == nil {
+		return nil, repository.ErrNotFound
+	}
+	return f.card, nil
+}
+
+func (f *fakeGiftCardRepo) Debit(ctx context.Context, code string, amount int64, now time.Time) (bool, error) {
+	f.debits = append(f.debits, amount)
+	if f.afterDebit != nil {
+		f.card = f.afterDebit
+	}
+	return f.applyDebit, nil
+}
+
+func giftCardServiceAt(repo giftCardRepo, now time.Time) *GiftCardService {
+	s := NewGiftCardService(repo)
+	s.now = func() time.Time { return now }
+	return s
+}
+
+func TestGiftCardRedeem(t *testing.T) {
+	now := time.Date(2026, 10, 8, 12, 0, 0, 0, time.UTC)
+	past := now.Add(-time.Hour)
+	future := now.Add(time.Hour)
+
+	t.Run("debits a card with enough balance", func(t *testing.T) {
+		repo := &fakeGiftCardRepo{card: &GiftCard{Code: "GC-1", Balance: 50_000, ExpiresAt: &future}, applyDebit: true}
+		if err := giftCardServiceAt(repo, now).Redeem(context.Background(), " gc-1 ", 50_000); err != nil {
+			t.Fatalf("expected the redemption to go through, got %v", err)
+		}
+		if len(repo.debits) != 1 || repo.debits[0] != 50_000 {
+			t.Fatalf("expected one 50000 debit, got %v", repo.debits)
+		}
+	})
+
+	t.Run("refuses a balance below the amount without writing", func(t *testing.T) {
+		repo := &fakeGiftCardRepo{card: &GiftCard{Code: "GC-1", Balance: 49_999}, applyDebit: true}
+		err := giftCardServiceAt(repo, now).Redeem(context.Background(), "GC-1", 50_000)
+		if !errors.Is(err, ErrGiftCardInsufficient) {
+			t.Fatalf("expected ErrGiftCardInsufficient, got %v", err)
+		}
+		if len(repo.debits) != 0 {
+			t.Fatalf("expected no debit attempt, got %v", repo.debits)
+		}
+	})
+
+	t.Run("refuses an expired card even when the balance covers it", func(t *testing.T) {
+		repo := &fakeGiftCardRepo{card: &GiftCard{Code: "GC-1", Balance: 500_000, ExpiresAt: &past}, applyDebit: true}
+		err := giftCardServiceAt(repo, now).Redeem(context.Background(), "GC-1", 50_000)
+		if !errors.Is(err, ErrGiftCardExpired) {
+			t.Fatalf("expected ErrGiftCardExpired, got %v", err)
+		}
+		if len(repo.debits) != 0 {
+			t.Fatalf("expected no debit attempt, got %v", repo.debits)
+		}
+	})
+
+	t.Run("expiry is exclusive at the instant itself", func(t *testing.T) {
+		at := now
+		repo := &fakeGiftCardRepo{card: &GiftCard{Code: "GC-1", Balance: 500_000, ExpiresAt: &at}, applyDebit: true}
+		if err := giftCardServiceAt(repo, now).Redeem(context.Background(), "GC-1", 1); !errors.Is(err, ErrGiftCardExpired) {
+			t.Fatalf("expected ErrGiftCardExpired at the expiry instant, got %v", err)
+		}
+	})
+
+	t.Run("a nil expiry never expires", func(t *testing.T) {
+		repo := &fakeGiftCardRepo{card: &GiftCard{Code: "GC-1", Balance: 1_000}, applyDebit: true}
+		if err := giftCardServiceAt(repo, now).Redeem(context.Background(), "GC-1", 1_000); err != nil {
+			t.Fatalf("expected the redemption to go through, got %v", err)
+		}
+	})
+
+	t.Run("a lost race comes back as a refusal, not as an overdrawn card", func(t *testing.T) {
+		repo := &fakeGiftCardRepo{
+			card:       &GiftCard{Code: "GC-1", Balance: 50_000},
+			applyDebit: false,
